# Catechism bank — the tawābiʿ Q&A (research/sources/mensubat.txt, third section, items 1-9).
ITEMS = [
 {"n": 1, "q": {"tr": "Tevâbi'in tarifi nedir? Tevâbi' kaçtır?", "en": "How are the followers (tawābiʿ) defined, and how many are they?"},
  "a": {"tr": "Metbûunun i'râbıyla tek cihetten i'râblanan her ikincidir. Beştir: sıfat, atıf, te'kîd, bedel, atf-ı beyân.", "en": "Every second word declined with its predecessor's iʿrāb from one side. Five: the adjective, coordination, emphasis, the badal and explanatory apposition."},
  "ar": ["كُلُّ ثَانٍ بِإِعْرَابِ سَابِقِهِ مِنْ جِهَةٍ وَاحِدَةٍ"], "notes": ["al-tawabi-wal-sifa", "tarifat-daftar-al-kafiya"], "story": "al-kafiya", "chapter": 46},
 {"n": 2, "q": {"tr": "Na'tın (sıfatın) tarifi nedir? Faydası nedir? Haber cümlesiyle ne vasıflanır?", "en": "How is the adjective (naʿt) defined, what is it for, and what may a declarative sentence describe?"},
  "a": {"tr": "Metbûundaki bir mânâya mutlak olarak delâlet eden tâbidir. Faydası: nekrede tahsis (رَجُلٌ عَالِمٌ), ma'rifede tavzih (زَيْدٌ التَّاجِرُ); bazen sırf övgü (بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ), sırf yergi (أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ), sırf te'kîd (نَفْخَةٌ وَاحِدَةٌ). Müştak olup olmaması fark etmez (رَجُلٌ عَالِمٌ، رَجُلٌ عَدْلٌ). Nekre haber cümlesiyle vasıflanır ve cümlede nekreye dönen bir zamir gerekir (جَاءَنِي رَجُلٌ أَبُوهُ قَائِمٌ); dönen zamir yoksa cümle yabancıdır ve sıfat olamaz.",
        "en": "A follower signifying, absolutely, a meaning in its predecessor. Its use: particularising an indefinite (رَجُلٌ عَالِمٌ), clarifying a definite (زَيْدٌ التَّاجِرُ); sometimes pure praise (بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ), pure blame (أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ), pure emphasis (نَفْخَةٌ وَاحِدَةٌ). Derived or not makes no difference (رَجُلٌ عَالِمٌ، رَجُلٌ عَدْلٌ). An indefinite may be described by a declarative sentence holding a pronoun that points back at it (جَاءَنِي رَجُلٌ أَبُوهُ قَائِمٌ); without that pronoun the sentence is a stranger and no adjective."},
  "ar": ["تَابِعٌ يَدُلُّ عَلَى مَعْنًى فِي مَتْبُوعِهِ مُطْلَقًا", "رَجُلٌ عَالِمٌ", "زَيْدٌ التَّاجِرُ", "جَاءَنِي رَجُلٌ أَبُوهُ قَائِمٌ"], "notes": ["naat-sifa", "al-tawabi-wal-sifa", "jumla-sifa"]},
 {"n": 3, "q": {"tr": "Sıfat, mevsûfun hâliyle vasıflandığında kaç yerde mevsûfa uyar?", "en": "When the adjective describes the state of its noun itself, in how many things does it agree?"},
  "a": {"tr": "On yerde: i'râb (ref', nasb, cer), ma'rife, nekre, müfred, tesniye, cem', müzekker, müennes — جَاءَنِي رَجُلٌ عَالِمٌ.", "en": "In ten: the three cases, definite, indefinite, singular, dual, plural, masculine, feminine — جَاءَنِي رَجُلٌ عَالِمٌ."},
  "ar": ["جَاءَنِي رَجُلٌ عَالِمٌ"], "notes": ["naat-sifa", "al-tawabi-wal-sifa"]},
 {"n": 4, "q": {"tr": "Sıfat ne zaman mevsûfun müteallakının hâliyle vasıflanır? O zaman kaç yerde uyar?", "en": "When does the adjective describe the state of something tied to its noun, and how far does it then agree?"},
  "a": {"tr": "Sarfî sıfat olup zâhir fâilinde amel ettiğinde (مَرَرْتُ بِرَجُلٍ حَسَنٍ غُلَامُهُ). O zaman ilk beşte (ref', nasb, cer, ma'rife, nekre) mevsûfa uyar; kalanında fiil gibidir: fâil müfred, tesniye ya da cem' olsa da sıfat müfred kalır (مَرَرْتُ بِرَجُلٍ قَاعِدٍ غِلْمَانُهُ); fâil müzekker ya da fasılasız hakikî müennes ise sıfat fâile uyar (مَرَرْتُ بِامْرَأَةٍ قَائِمٍ أَبُوهَا); fâil gayr-i hakikî müennes ya da fasılalı hakikî müennes ise iki vecih câizdir (مَرَرْتُ بِرَجُلٍ مَعْمُورٍ / مَعْمُورَةٍ دَارُهُ).",
        "en": "When it is a derived adjective governing an overt doer (مَرَرْتُ بِرَجُلٍ حَسَنٍ غُلَامُهُ). Then it agrees in the first five (case, definite, indefinite) and behaves like a verb in the rest: it stays singular whatever the doer's number (مَرَرْتُ بِرَجُلٍ قَاعِدٍ غِلْمَانُهُ); it follows the doer's gender when the doer is masculine or a real feminine with nothing between (مَرَرْتُ بِامْرَأَةٍ قَائِمٍ أَبُوهَا); with a figurative feminine, or a real one separated from it, both are allowed (مَرَرْتُ بِرَجُلٍ مَعْمُورٍ / مَعْمُورَةٍ دَارُهُ)."},
  "ar": ["مَرَرْتُ بِرَجُلٍ حَسَنٍ غُلَامُهُ", "مَرَرْتُ بِامْرَأَةٍ قَائِمٍ أَبُوهَا"], "notes": ["naat-sifa", "shurut-amal-ism-al-fail", "al-fail-al-muzhar-wa-tanith-amilih"]},
 {"n": 5, "q": {"tr": "Zamirler mevsûf ya da sıfat olur mu?", "en": "May pronouns be described, or be adjectives?"},
  "a": {"tr": "Olmazlar. Mevsûf olmazlar, çünkü ma'rifelerin en ma'rifesidir, sıfata ihtiyaçları yoktur. Sıfat olmazlar, çünkü mevsûfun sıfattan daha husûsî ya da ona eşit olması şarttır.",
        "en": "Neither. Not described, being the most definite of definites and needing no adjective; not adjectives, since the described must be more particular than, or equal to, its adjective."},
  "ar": [], "notes": ["naat-sifa", "al-marifa-al-mudmarat-wal-alam"]},
 {"n": 6, "q": {"tr": "Atfın tarifi nedir? Atıf harfleri nelerdir? Merfû muttasıl ve mecrûr muttasıl zamire atfın şartı nedir?", "en": "How is coordination defined, what are its letters, and what is required to coordinate to an attached rafʿ pronoun or jarr pronoun?"},
  "a": {"tr": "Metbûuyla birlikte nisbetle kastedilen, kendisiyle metbûu arasını on harften birinin ortaladığı tâbidir. Harfler: وَاوْ، فَا، ثُمَّ، حَتَّى، أَوْ، إِمَّا، أَمْ، لَا، بَلْ، لَكِنْ. Merfû muttasıl zamire atıfta, kelimenin cüzü gibi olan fâile atıf lâzım gelmesin diye önce munfasıl zamirle te'kîd edilir (ضَرَبْتُ أَنَا وَزَيْدٌ). Mecrûr muttasıl zamire atıfta, cârrın mecrûruna bitişmesi fâilin fiile bitişmesinden kuvvetli olduğundan cârr iade edilir (مَرَرْتُ بِكَ وَبِزَيْدٍ).",
        "en": "A follower meant along with its predecessor in the attribution, with one of ten letters between them: وَاوْ، فَا، ثُمَّ، حَتَّى، أَوْ، إِمَّا، أَمْ، لَا، بَلْ، لَكِنْ. To coordinate to an attached rafʿ pronoun it is first confirmed by a detached one, lest one coordinate to what is like a part of the word (ضَرَبْتُ أَنَا وَزَيْدٌ); to coordinate to an attached jarr pronoun the jarr letter is repeated, since its hold on its noun is firmer than a doer's on its verb (مَرَرْتُ بِكَ وَبِزَيْدٍ)."},
  "ar": ["تَابِعٌ مَقْصُودٌ بِالنِّسْبَةِ مَعَ مَتْبُوعِهِ يَتَوَسَّطُ بَيْنَهُ وَبَيْنَ مَتْبُوعِهِ أَحَدُ الْحُرُوفِ الْعَشَرَةِ", "ضَرَبْتُ أَنَا وَزَيْدٌ", "مَرَرْتُ بِكَ وَبِزَيْدٍ"], "notes": ["atf-nasaq", "al-atf-bil-huruf-wa-ahkamuh", "huruf-al-atf-fil-kafiya"]},
 {"n": 7, "q": {"tr": "مَا زَيْدٌ بِقَائِمٍ وَلَا ذَاهِبٌ عَمْرٌو، الَّذِي يَطِيرُ فَيَغْضَبُ زَيْدٌ الذُّبَابُ، فِي الدَّارِ زَيْدٌ وَالْحُجْرَةِ عَمْرٌو misallerinin izahı nasıldır?", "en": "Explain مَا زَيْدٌ بِقَائِمٍ وَلَا ذَاهِبٌ عَمْرٌو, الَّذِي يَطِيرُ فَيَغْضَبُ زَيْدٌ الذُّبَابُ and فِي الدَّارِ زَيْدٌ وَالْحُجْرَةِ عَمْرٌو."},
  "a": {"tr": "İlkinde ذَاهِبٌ'da yalnız ref' vâciptir: nasb ya da cerle قَائِمٍ'e atfedilse زَيْد'e haber olması gerekirdi, fakat زَيْد'e dönen zamirden boş olduğu için haber olamaz; bu yüzden عَمْرٌو muahhar mübteda, ذَاهِبٌ mukaddem haber olur ve cümle cümleye atfedilir. İkincisinde fâ sebebiyye olduğu için câizdir. Üçüncüsünde cârr öne geçtiğinden iki ayrı âmilin iki ma'mûlü üzerine bir atıf harfiyle iki şey atfetmek câiz olmuştur.",
        "en": "In the first only rafʿ is possible for ذَاهِبٌ: joined to قَائِمٍ in naṣb or jarr it would have to be a khabar of زَيْد, but it holds no pronoun pointing at him, so عَمْرٌو is a delayed mubtadaʾ and ذَاهِبٌ its fronted khabar — sentence joined to sentence. The second is allowed because the fāʾ is causal. In the third the jarr letter stands first, so two words may be joined by one letter onto the governed words of two different governors."},
  "ar": ["مَا زَيْدٌ بِقَائِمٍ وَلَا ذَاهِبٌ عَمْرٌو", "فِي الدَّارِ زَيْدٌ وَالْحُجْرَةِ عَمْرٌو"], "notes": ["atf-nasaq", "al-atf-bil-huruf-wa-ahkamuh"]},
 {"n": 8, "q": {"tr": "Te'kîdin tarifi nedir? Kaç kısımdır?", "en": "How is emphasis defined, and how many kinds has it?"},
  "a": {"tr": "Metbûunun durumunu nisbette ya da şümulde pekiştiren tâbidir. İki kısım: lafzî — ilk lafzın tekrarı, her lafızda geçerlidir: fiilde ضَرَبَ ضَرَبَ زَيْدٌ عَمْرًا, isimde جَاءَنِي زَيْدٌ زَيْدٌ, harfte إِنَّ إِنَّ زَيْدًا قَائِمٌ; manevî — dokuz lafza mahsustur: نَفْسُهُ، عَيْنُهُ، كِلَاهُمَا، كِلْتَاهُمَا، كُلُّهُ، أَجْمَعُ، أَكْتَعُ، أَبْتَعُ، أَبْصَعُ. كُلّ ve أَجْمَع ile yalnız cüzleri olanlar te'kîd edilir; أَكْتَعُ، أَبْتَعُ، أَبْصَعُ ise أَجْمَعُ'ye tâbidir, onun önüne geçmez ve onsuz zikredilmeleri zayıftır.",
        "en": "A follower confirming its predecessor's state, in attribution or in inclusiveness. Two kinds: in wording — repeating the first word, with a verb (ضَرَبَ ضَرَبَ زَيْدٌ عَمْرًا), a noun (جَاءَنِي زَيْدٌ زَيْدٌ) or a particle (إِنَّ إِنَّ زَيْدًا قَائِمٌ); in meaning — by nine set words: نَفْسُهُ، عَيْنُهُ، كِلَاهُمَا، كِلْتَاهُمَا، كُلُّهُ، أَجْمَعُ، أَكْتَعُ، أَبْتَعُ، أَبْصَعُ. كُلّ and أَجْمَع confirm only what has parts; أَكْتَعُ، أَبْتَعُ، أَبْصَعُ follow أَجْمَعُ, never precede it, and are weak without it."},
  "ar": ["تَابِعٌ يُقَرِّرُ أَمْرَ الْمَتْبُوعِ فِي النِّسْبَةِ أَوِ الشُّمُولِ", "جَاءَنِي زَيْدٌ زَيْدٌ", "إِنَّ إِنَّ زَيْدًا قَائِمٌ"], "notes": ["tawkid", "al-tawkid-al-lafzi-wal-manawi"]},
 {"n": 9, "q": {"tr": "Bedelin tarifi nedir? Bedel kaç kısımdır? Bedel ve mübdelün minhin ma'rife ve nekre olmasının hükmü nedir?", "en": "How is the badal defined, how many kinds has it, and may the badal and its predecessor be definite or indefinite?"},
  "a": {"tr": "Metbûuna nisbet edilen şeyle, metbûu değil kendisi kastedilen tâbidir. Dört kısım: bedel-i küll — ikisinin medlûlü bir olursa (جَاءَنِي زَيْدٌ أَخُوكَ); bedel-i ba'z — bedel mübdelün minhin bir cüzü olursa (ضَرَبْتُ زَيْدًا رَأْسَهُ); bedel-i iştimâl — aralarında küllîlik ve cüz'îlik dışında bir alâka olursa (سُلِبَ زَيْدٌ ثَوْبُهُ); bedel-i galat — mübdelün minhte yanıldıktan sonra alâka gözetmeksizin bedel kastedilirse (رَأَيْتُ رَجُلًا حِمَارًا). İkisi de ma'rife (جَاءَنِي زَيْدٌ أَخُوكَ) ya da nekre (جَاءَنِي رَجُلٌ غُلَامٌ لَكَ) olabilir; mübdelün minh ma'rife, bedel nekre (بِالنَّاصِيَةِ نَاصِيَةٍ كَاذِبَةٍ) ya da tersi (جَاءَنِي رَجُلٌ غُلَامُ زَيْدٍ) olabilir. Nekre ma'rifeden bedel kılınınca bir sıfatla vasıflanması lâzımdır.",
        "en": "A follower meant by what is attributed to its predecessor — meant itself, not the predecessor. Four kinds: the whole — both denote one thing (جَاءَنِي زَيْدٌ أَخُوكَ); the part — the badal is a part of the predecessor (ضَرَبْتُ زَيْدًا رَأْسَهُ); inclusion — a relation other than whole and part (سُلِبَ زَيْدٌ ثَوْبُهُ); the slip — after an error, a badal with no relation in view (رَأَيْتُ رَجُلًا حِمَارًا). Both may be definite (جَاءَنِي زَيْدٌ أَخُوكَ) or indefinite (جَاءَنِي رَجُلٌ غُلَامٌ لَكَ); the predecessor definite and the badal indefinite (بِالنَّاصِيَةِ نَاصِيَةٍ كَاذِبَةٍ), or the reverse (جَاءَنِي رَجُلٌ غُلَامُ زَيْدٍ). An indefinite standing as badal of a definite must carry an adjective."},
  "ar": ["تَابِعٌ مَقْصُودٌ بِمَا نُسِبَ إِلَى الْمَتْبُوعِ دُونَهُ", "جَاءَنِي زَيْدٌ أَخُوكَ", "ضَرَبْتُ زَيْدًا رَأْسَهُ", "سُلِبَ زَيْدٌ ثَوْبُهُ", "بِالنَّاصِيَةِ نَاصِيَةٍ كَاذِبَةٍ"], "notes": ["badal", "al-badal-wa-aqsamuh-wa-atf-al-bayan"]},
 {"n": 10, "q": {"tr": "Atf-ı beyânın tarifi nedir? Lafzan bedelden farkı nedir?", "en": "How is explanatory apposition (ʿaṭf al-bayān) defined, and how does it differ in wording from the badal?"},
  "a": {"tr": "Metbûunu açıklayan, sıfat olmayan tâbidir: أَقْسَمَ بِاللهِ أَبُو حَفْصٍ عُمَرُ * مَا مَسَّهَا مِنْ نَقَبٍ وَلَا دَبَرِ — عُمَرُ, أَبُو حَفْصٍ'ın atf-ı beyânıdır. Bedelden farkı أَنَا ابْنُ التَّارِكِ الْبِكْرِيِّ بِشْرٍ'de görünür: بِشْرٍ atf-ı beyân olabilir, bedel olamaz; çünkü bedel âmilin tekrarı kuvvetindedir, takdir أَنَا ابْنُ التَّارِكِ بِشْرٍ olur ve التَّارِكُ بِشْرٍ terkibi câiz olmayan الضَّارِبُ زَيْدٍ'e benzer.",
        "en": "A follower, not an adjective, that makes its predecessor clear: أَقْسَمَ بِاللهِ أَبُو حَفْصٍ عُمَرُ * مَا مَسَّهَا مِنْ نَقَبٍ وَلَا دَبَرِ — عُمَرُ explains أَبُو حَفْصٍ. The difference from the badal shows in أَنَا ابْنُ التَّارِكِ الْبِكْرِيِّ بِشْرٍ: بِشْرٍ may be explanatory apposition but not a badal, for a badal has the force of repeating the governor, which would give أَنَا ابْنُ التَّارِكِ بِشْرٍ — and التَّارِكُ بِشْرٍ is like the disallowed الضَّارِبُ زَيْدٍ."},
  "ar": ["تَابِعٌ غَيْرُ صِفَةٍ يُوضِحُ مَتْبُوعَهُ", "أَقْسَمَ بِاللهِ أَبُو حَفْصٍ عُمَرُ مَا مَسَّهَا مِنْ نَقَبٍ وَلَا دَبَرِ", "أَنَا ابْنُ التَّارِكِ الْبِكْرِيِّ بِشْرٍ"], "notes": ["atf-bayan", "al-badal-wa-aqsamuh-wa-atf-al-bayan"]},
]
